{
  "tables": [
    {
      "table": "marts.dim_sku",
      "description": "One row per SKU with its units and VAT rate."
    },
    {
      "table": "marts.dim_store",
      "description": "One row per store, with its POS sync state at the snapshot."
    },
    {
      "table": "marts.fct_goods_received",
      "description": "Stock received by each store, one row per batch, from suppliers or from other stores. Includes the opening stock received before the sales window."
    },
    {
      "table": "marts.fct_inventory_batch",
      "description": "Stock at the snapshot, one row per batch, in base units. On-hand still includes stock reserved for transfers in transit and expired stock that waits for the monthly write-off."
    },
    {
      "table": "marts.fct_returns",
      "description": "One row per returned item, with the return date and the original sale date when known."
    },
    {
      "table": "marts.fct_sales",
      "description": "One row per sales line from both POS vendors, retries removed, base units, with and without VAT."
    },
    {
      "table": "marts.fct_transfers",
      "description": "Store to store transfers in base units."
    },
    {
      "table": "marts.metricflow_time_spine",
      "description": "One row per day for MetricFlow's cumulative windows and time offsets."
    }
  ]
}

{
  "table": "marts.fct_sales",
  "columns": [
    {
      "name": "sales_line_id",
      "type": "VARCHAR",
      "description": "Vendor, receipt and line number joined."
    },
    {
      "name": "pos_vendor",
      "type": "VARCHAR",
      "description": "POS vendor, A or B."
    },
    {
      "name": "receipt_no",
      "type": "VARCHAR",
      "description": "Receipt number. Not unique per SKU, a receipt can hold the same SKU twice."
    },
    {
      "name": "line_no",
      "type": "INTEGER",
      "description": "Line number within the receipt."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store code."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "business_date",
      "type": "DATE",
      "description": "Local date of the sale."
    },
    {
      "name": "sold_at",
      "type": "TIMESTAMP",
      "description": "Local time of the sale."
    },
    {
      "name": "uom_code",
      "type": "VARCHAR",
      "description": "Unit sold."
    },
    {
      "name": "qty",
      "type": "INTEGER",
      "description": "Quantity in uom_code."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "vat_rate",
      "type": "DECIMAL(5,4)",
      "description": "VAT rate as a fraction."
    },
    {
      "name": "unit_price_incl_vat",
      "type": "BIGINT",
      "description": "Shelf price of one uom_code, VAT included."
    },
    {
      "name": "gross_incl_vat",
      "type": "BIGINT",
      "description": "Before discount, VAT included."
    },
    {
      "name": "discount_incl_vat",
      "type": "BIGINT",
      "description": "Discount, VAT included."
    },
    {
      "name": "amount_incl_vat",
      "type": "BIGINT",
      "description": "Paid, VAT included."
    },
    {
      "name": "gross_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Before discount, VAT excluded."
    },
    {
      "name": "discount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Discount, VAT excluded."
    },
    {
      "name": "amount_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Paid, VAT excluded."
    },
    {
      "name": "unit_cost_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Weighted average cost of one base unit of the SKU at this store (DR-008)."
    },
    {
      "name": "cogs_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Cost of goods sold for the line, qty_base times unit_cost_excl_vat."
    }
  ]
}

{
  "table": "marts.fct_returns",
  "columns": [
    {
      "name": "return_line_id",
      "type": "VARCHAR",
      "description": "Return id and line number joined."
    },
    {
      "name": "return_id",
      "type": "VARCHAR",
      "description": "Returns system id."
    },
    {
      "name": "line_no",
      "type": "INTEGER",
      "description": "Position within the return."
    },
    {
      "name": "store_code",
      "type": "VARCHAR",
      "description": "Store where the item came back."
    },
    {
      "name": "sku_code",
      "type": "VARCHAR",
      "description": "ERP item number."
    },
    {
      "name": "return_date",
      "type": "DATE",
      "description": "Local date of the return."
    },
    {
      "name": "returned_at",
      "type": "TIMESTAMP",
      "description": "Local time of the return."
    },
    {
      "name": "original_receipt_no",
      "type": "VARCHAR",
      "description": "Receipt of the original sale, null when the customer had none."
    },
    {
      "name": "sale_business_date",
      "type": "DATE",
      "description": "Business date of the original sale, null when it is not in the extract."
    },
    {
      "name": "has_matching_sale",
      "type": "BOOLEAN",
      "description": "True when the original sale was found."
    },
    {
      "name": "uom_code",
      "type": "VARCHAR",
      "description": "Unit returned."
    },
    {
      "name": "qty",
      "type": "INTEGER",
      "description": "Quantity in uom_code."
    },
    {
      "name": "qty_base",
      "type": "INTEGER",
      "description": "Quantity in base units."
    },
    {
      "name": "vat_rate",
      "type": "DECIMAL(5,4)",
      "description": "VAT rate as a fraction."
    },
    {
      "name": "refund_incl_vat",
      "type": "BIGINT",
      "description": "Refunded, VAT included."
    },
    {
      "name": "refund_excl_vat",
      "type": "DECIMAL(18,4)",
      "description": "Refunded, VAT excluded."
    },
    {
      "name": "return_reason",
      "type": "VARCHAR",
      "description": "Reason code."
    }
  ]
}

{
  "query": "select sum(amount_excl_vat) rev, sum(cogs_excl_vat) cogs, (sum(amount_excl_vat)-sum(cogs_excl_vat))/sum(amount_excl_vat) gm, count(*) n, sum(case when cogs_excl_vat is null then 1 else 0 end) nullcogs from marts.fct_sales where business_date between '2026-08-01' and '2026-08-31'"
}

{
  "value": 0.3327978149140678,
  "replacement_metric": null,
  "caveats": [],
  "explanation": "I summed paid revenue excluding VAT and COGS from marts.fct_sales for 2026-08-01 to 2026-08-31. Revenue was 7,442,338,601.72 VND and COGS was 4,965,544,577.22 VND, so gross margin is (revenue \u2212 COGS) / revenue \u2248 33.28%. I did not subtract returns from revenue. The tools reported no caveats."
}
